insert into public.fonts_astronomiques (codi, organitzacio, titol, url, any_publicacio, consultat_el) values
  ('imo-2026', 'IMO', '2026 Meteor Shower Calendar', 'https://www.imo.net/files/meteor-shower/cal2026.pdf', 2025, '2026-10-11'),
  ('imo-2027', 'IMO', '2027 Meteor Shower Calendar', 'https://www.imo.net/meteor-shower-calendar-2027/ShCal27s.pdf', 2026, '2026-10-11'),
  ('nasa-eclipsis-2027', 'NASA', 'Eclipses During 2027', 'https://eclipse.gsfc.nasa.gov/OH/OH2027.html', null, '2026-10-11')
insert into public.fenomens_astronomics (codi, tipus_codi, periodicitat, publicable_calendari, velocitat_km_s, textos) values
  ('draconids', 'pluja_estels', 'anual', true, 20, '{"ca":{"nom":"Dracònids","descripcio":"Pluja lenta d''origen cometari que sol tenir poca activitat, però que alguns anys pot presentar esclats inesperats.","consell_general":"Observeu-la al vespre des d''un lloc fosc i amb una vista àmplia del cel; no cal cap instrument."},"es":{"nom":"Dracónidas","descripcio":"Lluvia lenta de origen cometario que suele tener poca actividad, aunque algunos años puede presentar estallidos inesperados.","consell_general":"Obsérvala al anochecer desde un lugar oscuro con una vista amplia del cielo; no necesitas instrumentos."},"en":{"nom":"Draconids","descripcio":"A slow cometary meteor shower that is usually quiet, although some years bring unexpected outbursts.","consell_general":"Watch in the evening from a dark place with a wide view of the sky; no equipment is needed."}}'::jsonb),
  ('orionids', 'pluja_estels', 'anual', true, 66, '{"ca":{"nom":"Oriònids","descripcio":"Pluja anual de meteors ràpids associada al cometa Halley, amb un màxim habitualment ample.","consell_general":"Busqueu un cel fosc durant la segona meitat de la nit i mireu una zona extensa, lluny de la Lluna."},"es":{"nom":"Oriónidas","descripcio":"Lluvia anual de meteoros rápidos asociada al cometa Halley, con un máximo habitualmente amplio.","consell_general":"Busca un cielo oscuro durante la segunda mitad de la noche y observa una zona amplia, lejos de la Luna."},"en":{"nom":"Orionids","descripcio":"An annual shower of fast meteors associated with Halley''s Comet, usually with a broad peak.","consell_general":"Find a dark sky in the second half of the night and watch a broad area away from the Moon."}}'::jsonb),
  ('southern-taurids', 'pluja_estels', 'anual', true, 27, '{"ca":{"nom":"Tàurids del sud","descripcio":"Pluja de baixa freqüència i activitat molt estesa en el temps, coneguda per produir alguns meteors especialment brillants.","consell_general":"Cal paciència i un cel fosc; és més probable veure algun meteor brillant que una successió intensa."},"es":{"nom":"Táuridas del Sur","descripcio":"Lluvia de baja frecuencia y actividad muy extendida en el tiempo, conocida por producir algunos meteoros especialmente brillantes.","consell_general":"Ten paciencia y busca un cielo oscuro; es más probable ver algún meteoro brillante que una sucesión intensa."},"en":{"nom":"Southern Taurids","descripcio":"A low-rate shower spread over a long period, known for producing occasional exceptionally bright meteors.","consell_general":"Be patient under a dark sky; a bright meteor is more likely than a dense stream of meteors."}}'::jsonb),
  ('northern-taurids', 'pluja_estels', 'anual', true, 29, '{"ca":{"nom":"Tàurids del nord","descripcio":"Component nord del complex de les Tàurids, de taxa baixa i màxim ample, però amb possibilitat de meteors brillants.","consell_general":"Observeu a ull nu una zona gran del cel i assumiu que poden passar força minuts entre meteors."},"es":{"nom":"Táuridas del Norte","descripcio":"Componente septentrional del complejo de las Táuridas, de tasa baja y máximo amplio, pero con posibilidad de meteoros brillantes.","consell_general":"Observa a simple vista una zona amplia del cielo y cuenta con que pueden pasar bastantes minutos entre meteoros."},"en":{"nom":"Northern Taurids","descripcio":"The northern branch of the Taurid complex, with a low rate and broad peak but a chance of bright meteors.","consell_general":"Watch a wide area of the sky with the naked eye and expect several minutes between meteors."}}'::jsonb),
  ('leonids', 'pluja_estels', 'anual', true, 71, '{"ca":{"nom":"Leònids","descripcio":"Pluja de meteors molt ràpids que pot variar quan la Terra travessa traces de pols del seu cometa progenitor.","consell_general":"La segona meitat de la nit acostuma a ser la més adequada; deixeu que la vista s''adapti a la foscor."},"es":{"nom":"Leónidas","descripcio":"Lluvia de meteoros muy rápidos cuya actividad puede variar cuando la Tierra cruza rastros de polvo del cometa que la origina.","consell_general":"La segunda mitad de la noche suele ser la más adecuada; deja que la vista se adapte a la oscuridad."},"en":{"nom":"Leonids","descripcio":"A shower of very fast meteors whose activity can vary as Earth crosses dust trails from its parent comet.","consell_general":"The second half of the night is usually best; give your eyes time to adapt to the darkness."}}'::jsonb),
  ('geminids', 'pluja_estels', 'anual', true, 35, '{"ca":{"nom":"Gemínids","descripcio":"Una de les pluges anuals més abundants i regulars, amb meteors de velocitat moderada visibles durant bona part de la nit.","consell_general":"Observeu a ull nu des d''un indret fosc i protegit de llums directes; el radiant puja al llarg de la nit."},"es":{"nom":"Gemínidas","descripcio":"Una de las lluvias anuales más abundantes y regulares, con meteoros de velocidad moderada visibles durante buena parte de la noche.","consell_general":"Observa a simple vista desde un lugar oscuro y protegido de luces directas; el radiante asciende durante la noche."},"en":{"nom":"Geminids","descripcio":"One of the richest and most regular annual showers, with moderately fast meteors visible for much of the night.","consell_general":"Watch with the naked eye from a dark place sheltered from direct lights; the radiant rises during the night."}}'::jsonb),
  ('ursids', 'pluja_estels', 'anual', true, 33, '{"ca":{"nom":"Úrsids","descripcio":"Pluja boreal de final de desembre, normalment modesta però ben situada per a observadors de l''hemisferi nord.","consell_general":"Abrigueu-vos, trieu un horitzó poc il·luminat i reserveu una estona llarga d''observació."},"es":{"nom":"Úrsidas","descripcio":"Lluvia boreal de finales de diciembre, normalmente modesta pero bien situada para observadores del hemisferio norte.","consell_general":"Abrígate, elige un horizonte con poca iluminación y reserva un buen rato para observar."},"en":{"nom":"Ursids","descripcio":"A northern-hemisphere shower in late December, usually modest but well placed for northern observers.","consell_general":"Dress warmly, choose a dimly lit horizon and allow plenty of time to watch."}}'::jsonb),
  ('quadrantids', 'pluja_estels', 'anual', true, 41, '{"ca":{"nom":"Quadràntids","descripcio":"Pluja intensa de començament d''any amb un màxim relativament curt i un radiant favorable a latituds nord.","consell_general":"Convé observar tan a prop del màxim com sigui possible, perquè l''activitat alta dura menys que en altres pluges."},"es":{"nom":"Cuadrántidas","descripcio":"Lluvia intensa de comienzos de año con un máximo relativamente corto y un radiante favorable en latitudes septentrionales.","consell_general":"Conviene observar lo más cerca posible del máximo, porque la actividad alta dura menos que en otras lluvias."},"en":{"nom":"Quadrantids","descripcio":"An intense early-year shower with a relatively short peak and a radiant well placed at northern latitudes.","consell_general":"Observe as close to the peak as possible, because high activity lasts less time than in other showers."}}'::jsonb),
  ('lirids', 'pluja_estels', 'anual', true, 49, '{"ca":{"nom":"Lírides","descripcio":"Pluja anual de primavera amb activitat moderada i algun meteor brillant ocasional.","consell_general":"Observeu després de mitjanit des d''un cel fosc i eviteu tenir la Lluna o llums artificials dins del camp de visió."},"es":{"nom":"Líridas","descripcio":"Lluvia anual de primavera de actividad moderada, con algún meteoro brillante ocasional.","consell_general":"Observa después de medianoche desde un lugar oscuro y evita tener la Luna o luces artificiales en el campo de visión."},"en":{"nom":"Lyrids","descripcio":"An annual spring shower with moderate activity and occasional bright meteors.","consell_general":"Watch after midnight from a dark site and keep the Moon and artificial lights out of your field of view."}}'::jsonb),
  ('eta-aquariids', 'pluja_estels', 'anual', true, 66, '{"ca":{"nom":"Eta Aquàrids","descripcio":"Pluja ràpida associada al cometa Halley, molt activa al sud però amb el radiant baix vista des de Catalunya.","consell_general":"Cal observar poc abans de l''alba, amb l''horitzó est o sud-est ben lliure i sense esperar la taxa ideal anunciada."},"es":{"nom":"Eta Acuáridas","descripcio":"Lluvia rápida asociada al cometa Halley, muy activa al sur pero con el radiante bajo vista desde Cataluña.","consell_general":"Observa poco antes del amanecer, con el horizonte este o sureste despejado y sin esperar la tasa ideal anunciada."},"en":{"nom":"Eta Aquariids","descripcio":"A fast shower associated with Halley''s Comet, very active farther south but with a low radiant as seen from Catalonia.","consell_general":"Watch shortly before dawn with a clear eastern or southeastern horizon; do not expect the advertised ideal rate."}}'::jsonb),
  ('alpha-capricornids', 'pluja_estels', 'anual', true, 23, '{"ca":{"nom":"Alfa Capricòrnids","descripcio":"Pluja estival poc abundant, de meteors lents, que pot oferir bòlids vistosos malgrat la seva taxa baixa.","consell_general":"No espereu molts meteors: observeu amb paciència una àrea àmplia del cel per poder detectar els més brillants."},"es":{"nom":"Alfa Capricórnidas","descripcio":"Lluvia estival poco abundante de meteoros lentos que puede ofrecer bólidos vistosos pese a su tasa baja.","consell_general":"No esperes muchos meteoros: observa con paciencia una zona amplia del cielo para detectar los más brillantes."},"en":{"nom":"Alpha Capricornids","descripcio":"A sparse summer shower of slow meteors that can produce striking fireballs despite its low rate.","consell_general":"Do not expect many meteors: patiently watch a broad area of the sky for the brightest ones."}}'::jsonb),
  ('southern-delta-aquariids', 'pluja_estels', 'anual', true, 41, '{"ca":{"nom":"Delta Aquàrids del sud","descripcio":"Pluja d''estiu de durada llarga, més favorable a l''hemisferi sud però observable parcialment des de Catalunya.","consell_general":"Observeu de matinada cap a un cel obert al sud; la taxa real serà inferior a la ZHR ideal pel radiant baix."},"es":{"nom":"Delta Acuáridas del Sur","descripcio":"Lluvia estival de larga duración, más favorable en el hemisferio sur pero parcialmente observable desde Cataluña.","consell_general":"Observa de madrugada hacia un cielo abierto al sur; la tasa real será inferior a la ZHR ideal por la baja altura del radiante."},"en":{"nom":"Southern Delta Aquariids","descripcio":"A long-lasting summer shower better placed in the southern hemisphere but partly visible from Catalonia.","consell_general":"Watch before dawn with an open southern sky; the low radiant means the actual rate will be below the ideal ZHR."}}'::jsonb),
  ('perseids', 'pluja_estels', 'anual', true, 59, '{"ca":{"nom":"Perseids","descripcio":"Pluja d''estiu molt activa i popular, amb meteors ràpids i un radiant ben situat des de latituds mitjanes nord.","consell_general":"Observeu estirats i a ull nu des d''un lloc fosc; mirar una zona àmplia separada del radiant facilita veure traces llargues."},"es":{"nom":"Perseidas","descripcio":"Lluvia estival muy activa y popular, con meteoros rápidos y un radiante bien situado desde latitudes medias del hemisferio norte.","consell_general":"Observa tumbado y a simple vista desde un lugar oscuro; mirar una zona amplia alejada del radiante ayuda a ver trazas largas."},"en":{"nom":"Perseids","descripcio":"A very active and popular summer shower, with fast meteors and a radiant well placed at mid-northern latitudes.","consell_general":"Lie back and watch with the naked eye from a dark site; a wide area away from the radiant helps reveal long trails."}}'::jsonb),
  ('eclipsi-lunar-penumbral', 'eclipsi_llunar', 'ocasional', true, null, '{"ca":{"nom":"Eclipsi lunar penumbral","descripcio":"La Lluna travessa la penombra de la Terra i perd llum de manera gradual, sense arribar a entrar a l''ombra central.","consell_general":"El canvi pot ser molt subtil; compareu l''aspecte de la Lluna abans i durant el màxim o feu fotografies amb la mateixa exposició."},"es":{"nom":"Eclipse lunar penumbral","descripcio":"La Luna atraviesa la penumbra terrestre y pierde luminosidad gradualmente sin entrar en la sombra central.","consell_general":"El cambio puede ser muy sutil; compara el aspecto de la Luna antes y durante el máximo o toma fotografías con la misma exposición."},"en":{"nom":"Penumbral lunar eclipse","descripcio":"The Moon passes through Earth''s penumbra and gradually dims without entering the central shadow.","consell_general":"The change may be very subtle; compare the Moon before and during the peak or take photos with the same exposure."}}'::jsonb),
  ('eclipsi-solar-total', 'eclipsi_solar', 'ocasional', true, null, '{"ca":{"nom":"Eclipsi solar total","descripcio":"Eclipsi en què la Lluna cobreix completament el Sol dins la franja de totalitat; des d''altres llocs només se''n veu una fase parcial.","consell_general":"Fora de la totalitat, mireu el Sol només amb ulleres o visors solars conformes amb ISO 12312-2; els instruments necessiten un filtre solar frontal adequat."},"es":{"nom":"Eclipse solar total","descripcio":"Eclipse en el que la Luna cubre por completo el Sol dentro de la franja de totalidad; desde otros lugares solo se ve una fase parcial.","consell_general":"Fuera de la totalidad, observa el Sol solo con gafas o visores solares conformes con ISO 12312-2; los instrumentos necesitan un filtro solar frontal adecuado."},"en":{"nom":"Total solar eclipse","descripcio":"An eclipse in which the Moon fully covers the Sun within the path of totality; elsewhere only a partial phase is visible.","consell_general":"Outside totality, view the Sun only through solar glasses or viewers compliant with ISO 12312-2; optical instruments need a suitable front solar filter."}}'::jsonb)
insert into public.esdeveniments_astronomics (codi, fenomen_codi, font_codi, referencia_font, inici, fi, maxim, precisio, rellevant_catalunya, rellevancia, dificultat_observacio, zhr, radiant_maxim, textos) values
  ('draconids-2026', 'draconids', 'imo-2026', 'Taula 5 i apartat Draconids', '2026-10-06T00:00:00Z', '2026-10-10T23:59:59Z', '2026-10-09T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'mitjana', '{"valor":5,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":262,"declinacio_graus":54}'::jsonb, '{"ca":{"nota_visibilitat":"Observable des de Catalunya, però amb poca activitat habitual i sense cap augment previst per al 2026.","consell_observacio":"Proveu-ho al vespre del 9 d''octubre des d''un cel fosc i valoreu-la com una observació pacient, no com una pluja intensa."},"es":{"nota_visibilitat":"Observable desde Cataluña, aunque su actividad habitual es baja y no se prevé ningún aumento para 2026.","consell_observacio":"Pruébalo al anochecer del 9 de octubre bajo un cielo oscuro y plantéalo como una observación paciente, no como una lluvia intensa."},"en":{"nota_visibilitat":"Visible from Catalonia, but usually quiet, with no increase in activity predicted for 2026.","consell_observacio":"Try watching on the evening of 9 October under a dark sky; expect a patient observing session, not an intense shower."}}'::jsonb),
  ('orionids-2026', 'orionids', 'imo-2026', 'Taula 5 i apartat Orionids', '2026-10-02T00:00:00Z', '2026-11-07T23:59:59Z', '2026-10-21T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'principal', 'mitjana', '{"valor":20,"qualificador":"minim"}'::jsonb, '{"ascensio_recta_graus":95,"declinacio_graus":16}'::jsonb, '{"ca":{"nota_visibilitat":"El radiant és visible des de Catalunya i el màxim és prou ample perquè també siguin útils les nits pròximes.","consell_observacio":"Observeu durant la matinada del 21 d''octubre, quan Orió sigui més alt, des d''una zona sense llum directa."},"es":{"nota_visibilitat":"El radiante es visible desde Cataluña y el máximo es suficientemente amplio para que también sirvan las noches cercanas.","consell_observacio":"Observa durante la madrugada del 21 de octubre, cuando Orión esté más alto, desde un lugar sin luz directa."},"en":{"nota_visibilitat":"The radiant is visible from Catalonia, and the peak is broad enough for nearby nights to be worthwhile too.","consell_observacio":"Watch before dawn on 21 October, when Orion is higher, from a place without direct lighting."}}'::jsonb),
  ('southern-taurids-2026', 'southern-taurids', 'imo-2026', 'Taula 5', '2026-09-20T00:00:00Z', '2026-11-20T23:59:59Z', '2026-11-05T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'mitjana', '{"valor":7,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":52,"declinacio_graus":15}'::jsonb, '{"ca":{"nota_visibilitat":"Visible des de Catalunya amb una taxa baixa, però amb possibilitat de meteors brillants.","consell_observacio":"Dediqueu-hi una sessió llarga al voltant del 5 de novembre i no interpreteu la baixa freqüència com una incidència del servei."},"es":{"nota_visibilitat":"Visible desde Cataluña con una tasa baja, pero con posibilidad de meteoros brillantes.","consell_observacio":"Dedica una sesión larga alrededor del 5 de noviembre y no confundas la baja frecuencia con un fallo del servicio."},"en":{"nota_visibilitat":"Visible from Catalonia at a low rate, but with a chance of bright meteors.","consell_observacio":"Allow a long session around 5 November; a low meteor rate does not mean the service is malfunctioning."}}'::jsonb),
  ('northern-taurids-2026', 'northern-taurids', 'imo-2026', 'Taula 5', '2026-10-20T00:00:00Z', '2026-12-10T23:59:59Z', '2026-11-12T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'mitjana', '{"valor":5,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":58,"declinacio_graus":22}'::jsonb, '{"ca":{"nota_visibilitat":"Observable des de Catalunya, amb activitat baixa i distribuïda durant moltes nits.","consell_observacio":"Cerqueu un cel fosc pels volts del 12 de novembre i centreu l''expectativa en algun meteor brillant aïllat."},"es":{"nota_visibilitat":"Observable desde Cataluña, con actividad baja repartida a lo largo de muchas noches.","consell_observacio":"Busca un cielo oscuro alrededor del 12 de noviembre y espera algún meteoro brillante aislado."},"en":{"nota_visibilitat":"Visible from Catalonia, with low activity spread over many nights.","consell_observacio":"Find a dark sky around 12 November and look for an occasional isolated bright meteor."}}'::jsonb),
  ('leonids-2026', 'leonids', 'imo-2026', 'Taula 5 i apartat Leonids', '2026-11-06T00:00:00Z', '2026-11-30T23:59:59Z', '2026-11-17T23:45:00Z', '{"inici":"dia","fi":"dia","maxim":"minut"}'::jsonb, true, 'principal', 'mitjana', '{"valor":15,"qualificador":"aproximat"}'::jsonb, '{"ascensio_recta_graus":152,"declinacio_graus":22}'::jsonb, '{"ca":{"nota_visibilitat":"El radiant es pot observar des de Catalunya i guanya altura durant la matinada.","consell_observacio":"Prioritzeu la nit del 17 al 18 de novembre, especialment després de mitjanit."},"es":{"nota_visibilitat":"El radiante se puede observar desde Cataluña y gana altura durante la madrugada.","consell_observacio":"Prioriza la noche del 17 al 18 de noviembre, especialmente después de medianoche."},"en":{"nota_visibilitat":"The radiant can be seen from Catalonia and climbs higher before dawn.","consell_observacio":"Prioritize the night of 17–18 November, especially after midnight."}}'::jsonb),
  ('geminids-2026', 'geminids', 'imo-2026', 'Taula 5 i apartat Geminids', '2026-12-04T00:00:00Z', '2026-12-20T23:59:59Z', '2026-12-14T14:00:00Z', '{"inici":"dia","fi":"dia","maxim":"hora"}'::jsonb, true, 'principal', 'baixa', '{"valor":150,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":112,"declinacio_graus":33}'::jsonb, '{"ca":{"nota_visibilitat":"Màxim molt actiu i amb condicions lunars favorables durant la nit principal.","consell_observacio":"Observeu les nits del 13 al 14 i del 14 al 15 de desembre; el màxim diürn queda compensat per l''amplitud de l''activitat."},"es":{"nota_visibilitat":"Máximo muy activo, con condiciones lunares favorables durante la noche principal.","consell_observacio":"Observa las noches del 13 al 14 y del 14 al 15 de diciembre; la amplitud de la actividad compensa que el máximo ocurra de día."},"en":{"nota_visibilitat":"A very active peak with favourable Moon conditions during the main night.","consell_observacio":"Watch on the nights of 13–14 and 14–15 December; the broad activity makes up for the daytime peak."}}'::jsonb),
  ('ursids-2026', 'ursids', 'imo-2026', 'Taula 5 i resum de condicions del 2026', '2026-12-17T00:00:00Z', '2026-12-26T23:59:59Z', '2026-12-22T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'principal', 'alta', '{"valor":10,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":217,"declinacio_graus":76}'::jsonb, '{"ca":{"nota_visibilitat":"El radiant boreal és favorable, però la llum de la Lluna perjudicarà especialment el màxim de 2026.","consell_observacio":"Situeu la Lluna darrere d''un obstacle i busqueu un indret tan fosc com sigui possible la nit del 22 de desembre."},"es":{"nota_visibilitat":"El radiante septentrional está bien situado, pero la luz de la Luna dificultará especialmente el máximo de 2026.","consell_observacio":"Sitúa la Luna detrás de un obstáculo y busca un lugar lo más oscuro posible la noche del 22 de diciembre."},"en":{"nota_visibilitat":"The northern radiant is well placed, but moonlight will particularly hamper the 2026 peak.","consell_observacio":"Hide the Moon behind an obstacle and choose the darkest possible site on the night of 22 December."}}'::jsonb),
  ('quadrantids-2027', 'quadrantids', 'imo-2027', 'Taula 5 i apartat Quadrantids', '2026-12-28T00:00:00Z', '2027-01-12T23:59:59Z', '2027-01-04T03:25:00Z', '{"inici":"dia","fi":"dia","maxim":"minut"}'::jsonb, true, 'principal', 'mitjana', '{"valor":80,"qualificador":"minim"}'::jsonb, '{"ascensio_recta_graus":230,"declinacio_graus":49}'::jsonb, '{"ca":{"nota_visibilitat":"Màxim favorable des de Catalunya, poc abans de la Lluna nova, però concentrat en un interval curt.","consell_observacio":"Planifiqueu la matinada del 4 de gener i comenceu abans de les 03:25 UTC per no perdre el pic."},"es":{"nota_visibilitat":"Máximo favorable desde Cataluña, poco antes de la Luna nueva, pero concentrado en un intervalo corto.","consell_observacio":"Planea la madrugada del 4 de enero y empieza antes de las 03:25 UTC para no perder el pico."},"en":{"nota_visibilitat":"A favourable peak from Catalonia shortly before new Moon, although concentrated in a short interval.","consell_observacio":"Plan for the early hours of 4 January and start before 03:25 UTC so you do not miss the peak."}}'::jsonb),
  ('eclipsi-lunar-penumbral-2027-02-20', 'eclipsi-lunar-penumbral', 'nasa-eclipsis-2027', 'Taula de fases de l''eclipsi lunar penumbral del 20 de febrer', '2027-02-20T21:12:00Z', '2027-02-21T01:13:00Z', '2027-02-20T23:13:00Z', '{"inici":"minut","fi":"minut","maxim":"minut"}'::jsonb, true, 'principal', 'alta', null, null, '{"ca":{"nota_visibilitat":"L''eclipsi és visible des d''Europa i, per tant, des de Catalunya, però l''enfosquiment penumbral serà subtil.","consell_observacio":"Compareu la Lluna abans del màxim i cap a les 23:13 UTC; una fotografia amb exposició constant pot fer més evident el canvi."},"es":{"nota_visibilitat":"El eclipse es visible desde Europa y, por tanto, desde Cataluña, pero el oscurecimiento penumbral será sutil.","consell_observacio":"Compara la Luna antes del máximo y hacia las 23:13 UTC; una fotografía con exposición constante puede hacer más evidente el cambio."},"en":{"nota_visibilitat":"The eclipse is visible from Europe, including Catalonia, but the penumbral darkening will be subtle.","consell_observacio":"Compare the Moon before the peak and around 23:13 UTC; photos taken with the same exposure may make the change clearer."}}'::jsonb),
  ('lirids-2027', 'lirids', 'imo-2027', 'Taula 5 i apartat Lyrids', '2027-04-14T00:00:00Z', '2027-04-30T23:59:59Z', '2027-04-23T01:40:00Z', '{"inici":"dia","fi":"dia","maxim":"minut"}'::jsonb, true, 'principal', 'alta', '{"valor":18,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":271,"declinacio_graus":34}'::jsonb, '{"ca":{"nota_visibilitat":"El radiant és observable, però el màxim arriba poc després de la Lluna plena i se''n perdran els meteors febles.","consell_observacio":"Observeu la matinada del 23 d''abril mantenint la Lluna fora del camp visual."},"es":{"nota_visibilitat":"El radiante es observable, pero el máximo llega poco después de la Luna llena y se perderán los meteoros débiles.","consell_observacio":"Observa durante la madrugada del 23 de abril manteniendo la Luna fuera de tu campo de visión."},"en":{"nota_visibilitat":"The radiant is observable, but the peak comes shortly after full Moon, hiding faint meteors.","consell_observacio":"Watch before dawn on 23 April while keeping the Moon out of your field of view."}}'::jsonb),
  ('eta-aquariids-2027', 'eta-aquariids', 'imo-2027', 'Taula 5 i apartat Eta Aquariids', '2027-04-19T00:00:00Z', '2027-05-28T23:59:59Z', '2027-05-06T09:00:00Z', '{"inici":"dia","fi":"dia","maxim":"hora"}'::jsonb, true, 'principal', 'alta', '{"valor":50,"qualificador":"variable"}'::jsonb, '{"ascensio_recta_graus":338,"declinacio_graus":-1}'::jsonb, '{"ca":{"nota_visibilitat":"Des de Catalunya el radiant queda baix i només ofereix una finestra curta abans de l''alba; la taxa real serà molt inferior a la ZHR ideal.","consell_observacio":"Busqueu un horitzó est o sud-est completament lliure durant les matinades pròximes al 6 de maig."},"es":{"nota_visibilitat":"Desde Cataluña el radiante queda bajo y solo ofrece una ventana breve antes del amanecer; la tasa real será muy inferior a la ZHR ideal.","consell_observacio":"Busca un horizonte este o sureste completamente despejado durante las madrugadas cercanas al 6 de mayo."},"en":{"nota_visibilitat":"From Catalonia the radiant stays low, offering only a brief window before dawn; the actual rate will be far below the ideal ZHR.","consell_observacio":"Find a completely clear eastern or southeastern horizon on mornings around 6 May."}}'::jsonb),
  ('alpha-capricornids-2027', 'alpha-capricornids', 'imo-2027', 'Taula 5 i apartat Alpha Capricornids', '2027-07-03T00:00:00Z', '2027-08-15T23:59:59Z', '2027-07-31T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'mitjana', '{"valor":5,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":307,"declinacio_graus":-10}'::jsonb, '{"ca":{"nota_visibilitat":"Observable des de Catalunya amb una taxa baixa; l''interès principal són els possibles bòlids.","consell_observacio":"Observeu una zona àmplia del cel la nit del 30 al 31 de juliol i tingueu present que poden passar molts minuts sense activitat."},"es":{"nota_visibilitat":"Observable desde Cataluña con una tasa baja; el principal atractivo son los posibles bólidos.","consell_observacio":"Observa una zona amplia del cielo la noche del 30 al 31 de julio y ten en cuenta que pueden pasar muchos minutos sin actividad."},"en":{"nota_visibilitat":"Visible from Catalonia at a low rate; possible fireballs are the main attraction.","consell_observacio":"Watch a broad area of sky on the night of 30–31 July and expect long gaps without activity."}}'::jsonb),
  ('southern-delta-aquariids-2027', 'southern-delta-aquariids', 'imo-2027', 'Taula 5 i apartat Southern Delta Aquariids', '2027-07-12T00:00:00Z', '2027-08-23T23:59:59Z', '2027-07-31T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'principal', 'alta', '{"valor":25,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":340,"declinacio_graus":-16}'::jsonb, '{"ca":{"nota_visibilitat":"Només una part de l''activitat ideal és visible des de Catalunya perquè el radiant culmina baix sobre l''horitzó sud.","consell_observacio":"Prioritzeu les hores prèvies a l''alba del 31 de juliol des d''un lloc amb l''horitzó sud lliure."},"es":{"nota_visibilitat":"Solo una parte de la actividad ideal es visible desde Cataluña porque el radiante culmina bajo sobre el horizonte sur.","consell_observacio":"Prioriza las horas previas al amanecer del 31 de julio desde un lugar con el horizonte sur despejado."},"en":{"nota_visibilitat":"Only part of the ideal activity is visible from Catalonia because the radiant reaches a low altitude above the southern horizon.","consell_observacio":"Prioritize the hours before dawn on 31 July from a site with a clear southern horizon."}}'::jsonb),
  ('perseids-2027', 'perseids', 'imo-2027', 'Taula 5 i apartat Perseids; el camp maxim representa el punt mitjà de l''interval 08:00-10:00 UTC', '2027-07-17T00:00:00Z', '2027-08-24T23:59:59Z', '2027-08-13T09:00:00Z', '{"inici":"dia","fi":"dia","maxim":"hora"}'::jsonb, true, 'principal', 'mitjana', '{"valor":110,"qualificador":"minim"}'::jsonb, '{"ascensio_recta_graus":48,"declinacio_graus":58}'::jsonb, '{"ca":{"nota_visibilitat":"Molt ben situada des de Catalunya, tot i que la Lluna creixent reduirà el contrast dels meteors més febles.","consell_observacio":"El màxim previst és entre les 08:00 i les 10:00 UTC del 13 d''agost; observeu les nits immediatament anterior i posterior, amagant la Lluna de la vista."},"es":{"nota_visibilitat":"Muy bien situada desde Cataluña, aunque la Luna creciente reducirá el contraste de los meteoros más débiles.","consell_observacio":"El máximo previsto es entre las 08:00 y las 10:00 UTC del 13 de agosto; observa las noches inmediatamente anterior y posterior ocultando la Luna de la vista."},"en":{"nota_visibilitat":"Very well placed from Catalonia, although the waxing Moon will reduce the contrast of fainter meteors.","consell_observacio":"The predicted peak is between 08:00 and 10:00 UTC on 13 August; watch on the nights immediately before and after, keeping the Moon out of view."}}'::jsonb),
  ('eclipsi-solar-total-2027-08-02', 'eclipsi-solar-total', 'nasa-eclipsis-2027', 'Fases globals i màxim de l''eclipsi solar total del 2 d''agost', '2027-08-02T07:30:00Z', '2027-08-02T12:43:00Z', '2027-08-02T10:07:00Z', '{"inici":"minut","fi":"minut","maxim":"minut"}'::jsonb, true, 'principal', 'mitjana', null, null, '{"ca":{"nota_visibilitat":"L''eclipsi és total globalment, però des de Catalunya només se''n veu la fase parcial; les hores són els contactes globals, no els locals.","consell_observacio":"A Catalunya cal protecció solar homologada ISO 12312-2 durant tota l''observació. No useu ulleres de sol i poseu un filtre solar adequat davant de qualsevol telescopi, prismàtic o càmera."},"es":{"nota_visibilitat":"El eclipse es total a escala global, pero desde Cataluña solo se ve la fase parcial; las horas son las de los contactos globales, no las locales.","consell_observacio":"En Cataluña se necesita protección solar homologada ISO 12312-2 durante toda la observación. No uses gafas de sol y coloca un filtro solar adecuado delante de cualquier telescopio, prismático o cámara."},"en":{"nota_visibilitat":"The eclipse is total elsewhere in the world, but only the partial phase is visible from Catalonia; the times are global contacts, not local ones.","consell_observacio":"In Catalonia, use ISO 12312-2 compliant solar protection throughout the observation. Do not use ordinary sunglasses; fit a suitable solar filter in front of any telescope, binoculars or camera."}}'::jsonb),
  ('draconids-2027', 'draconids', 'imo-2027', 'Taula 5 i apartat Draconids', '2027-10-06T00:00:00Z', '2027-10-10T23:59:59Z', '2027-10-09T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'alta', '{"valor":5,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":263,"declinacio_graus":56}'::jsonb, '{"ca":{"nota_visibilitat":"Observable al vespre, però la baixa taxa habitual i la Lluna gibosa dificultaran l''observació de 2027.","consell_observacio":"Mantingueu la Lluna tapada per un edifici o relleu i considereu qualsevol meteor observat un resultat valuós."},"es":{"nota_visibilitat":"Observable al anochecer, pero la tasa habitual baja y la Luna gibosa dificultarán la observación de 2027.","consell_observacio":"Oculta la Luna tras un edificio o el relieve y considera valioso cualquier meteoro que veas."},"en":{"nota_visibilitat":"Visible in the evening, but the usually low rate and a gibbous Moon will make the 2027 shower harder to observe.","consell_observacio":"Block the Moon with a building or hillside and consider any meteor you see a worthwhile sighting."}}'::jsonb),
  ('orionids-2027', 'orionids', 'imo-2027', 'Taula 5 i apartat Orionids', '2027-10-02T00:00:00Z', '2027-11-07T23:59:59Z', '2027-10-22T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'principal', 'alta', '{"valor":20,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":95,"declinacio_graus":16}'::jsonb, '{"ca":{"nota_visibilitat":"El màxim ample és observable des de Catalunya, però una Lluna minvant brillant ocultarà part dels meteors.","consell_observacio":"Compareu diverses matinades al voltant del 22 d''octubre i situeu-vos de manera que la Lluna quedi fora de la vista."},"es":{"nota_visibilitat":"El máximo amplio es observable desde Cataluña, pero una Luna menguante brillante ocultará parte de los meteoros.","consell_observacio":"Compara varias madrugadas alrededor del 22 de octubre y sitúate de forma que la Luna quede fuera de la vista."},"en":{"nota_visibilitat":"The broad peak is visible from Catalonia, but a bright waning Moon will hide some meteors.","consell_observacio":"Compare several mornings around 22 October and position yourself so the Moon is out of view."}}'::jsonb),
  ('southern-taurids-2027', 'southern-taurids', 'imo-2027', 'Taula 5', '2027-09-20T00:00:00Z', '2027-11-20T23:59:59Z', '2027-11-06T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'mitjana', '{"valor":7,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":52,"declinacio_graus":15}'::jsonb, '{"ca":{"nota_visibilitat":"Visible des de Catalunya amb una freqüència baixa i un màxim poc concentrat.","consell_observacio":"Feu una observació llarga durant les nits pròximes al 6 de novembre i fixeu-vos especialment en meteors brillants."},"es":{"nota_visibilitat":"Visible desde Cataluña con una frecuencia baja y un máximo poco concentrado.","consell_observacio":"Dedica una observación larga a las noches cercanas al 6 de noviembre y fíjate especialmente en los meteoros brillantes."},"en":{"nota_visibilitat":"Visible from Catalonia at a low rate, with no sharply defined peak.","consell_observacio":"Allow a long observing session on nights around 6 November and pay particular attention to bright meteors."}}'::jsonb),
  ('northern-taurids-2027', 'northern-taurids', 'imo-2027', 'Taula 5', '2027-10-20T00:00:00Z', '2027-12-10T23:59:59Z', '2027-11-13T12:00:00Z', '{"inici":"dia","fi":"dia","maxim":"dia"}'::jsonb, true, 'secundari', 'mitjana', '{"valor":5,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":58,"declinacio_graus":22}'::jsonb, '{"ca":{"nota_visibilitat":"Observable des de Catalunya, però la taxa és baixa i l''activitat es reparteix en un període extens.","consell_observacio":"Observeu al voltant del 13 de novembre sense esperar un pic sobtat; l''interès principal són els meteors brillants."},"es":{"nota_visibilitat":"Observable desde Cataluña, pero la tasa es baja y la actividad se reparte durante un período largo.","consell_observacio":"Observa alrededor del 13 de noviembre sin esperar un pico repentino; lo más interesante son los meteoros brillantes."},"en":{"nota_visibilitat":"Visible from Catalonia, but the rate is low and activity is spread over a long period.","consell_observacio":"Watch around 13 November without expecting a sudden peak; bright meteors are the main attraction."}}'::jsonb),
  ('leonids-2027', 'leonids', 'imo-2027', 'Taula 5 i apartat Leonids', '2027-11-06T00:00:00Z', '2027-11-30T23:59:59Z', '2027-11-18T06:00:00Z', '{"inici":"dia","fi":"dia","maxim":"hora"}'::jsonb, true, 'principal', 'alta', '{"valor":15,"qualificador":"minim"}'::jsonb, '{"ascensio_recta_graus":152,"declinacio_graus":22}'::jsonb, '{"ca":{"nota_visibilitat":"El radiant és favorable, però la Lluna gibosa interferirà i només es detectaran amb facilitat els meteors més brillants.","consell_observacio":"Prioritzeu la matinada del 18 de novembre i, si és possible, repetiu l''observació els dies següents per possibles traces de pols."},"es":{"nota_visibilitat":"El radiante está bien situado, pero la Luna gibosa interferirá y solo los meteoros más brillantes se detectarán fácilmente.","consell_observacio":"Prioriza la madrugada del 18 de noviembre y, si puedes, repite la observación los días siguientes por posibles rastros de polvo."},"en":{"nota_visibilitat":"The radiant is well placed, but a gibbous Moon will interfere, so only brighter meteors will be easy to spot.","consell_observacio":"Prioritize the early hours of 18 November and, if possible, watch again on following days for possible dust trails."}}'::jsonb),
  ('geminids-2027', 'geminids', 'imo-2027', 'Taula 5 i apartat Geminids', '2027-12-04T00:00:00Z', '2027-12-20T23:59:59Z', '2027-12-14T20:00:00Z', '{"inici":"dia","fi":"dia","maxim":"hora"}'::jsonb, true, 'principal', 'alta', '{"valor":150,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":112,"declinacio_graus":33}'::jsonb, '{"ca":{"nota_visibilitat":"La pluja és intrínsecament molt activa, però la Lluna plena perjudicarà severament el màxim de 2027.","consell_observacio":"Observeu la nit del 14 de desembre amb la Lluna darrere d''un obstacle i espereu sobretot els meteors més lluminosos."},"es":{"nota_visibilitat":"La lluvia es intrínsecamente muy activa, pero la Luna llena perjudicará mucho el máximo de 2027.","consell_observacio":"Observa la noche del 14 de diciembre con la Luna detrás de un obstáculo y espera sobre todo los meteoros más luminosos."},"en":{"nota_visibilitat":"The shower is naturally very active, but the full Moon will strongly hamper the 2027 peak.","consell_observacio":"Watch on the night of 14 December with the Moon behind an obstacle and expect mainly the brightest meteors."}}'::jsonb),
  ('ursids-2027', 'ursids', 'imo-2027', 'Taula 5 i apartat Ursids', '2027-12-17T00:00:00Z', '2027-12-26T23:59:59Z', '2027-12-23T04:00:00Z', '{"inici":"dia","fi":"dia","maxim":"hora"}'::jsonb, true, 'principal', 'mitjana', '{"valor":10,"qualificador":"estimat"}'::jsonb, '{"ascensio_recta_graus":217,"declinacio_graus":76}'::jsonb, '{"ca":{"nota_visibilitat":"El radiant és ben situat des de Catalunya, però l''IMO no preveu cap augment especial d''activitat el 2027.","consell_observacio":"Observeu la matinada del 23 de desembre des d''un lloc fosc i reserveu almenys una hora per compensar la taxa moderada."},"es":{"nota_visibilitat":"El radiante está bien situado desde Cataluña, pero la IMO no prevé ningún aumento especial de actividad en 2027.","consell_observacio":"Observa durante la madrugada del 23 de diciembre desde un lugar oscuro y reserva al menos una hora para compensar la tasa moderada."},"en":{"nota_visibilitat":"The radiant is well placed from Catalonia, but the IMO predicts no special increase in activity for 2027.","consell_observacio":"Watch before dawn on 23 December from a dark site and allow at least an hour to make up for the moderate rate."}}'::jsonb)
